<?php
namespace App\Http\Controllers;
use App\Models\Order;use App\Models\Products;use App\Models\PurchaseOrder;use App\Models\StockMovement;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class ReportController extends Controller {private function manager(Request $r):void{abort_unless($r->user()?->isManager(),403);}public function index(Request $r){$this->manager($r);$products=Products::with('categoryRelation')->where('is_active',true)->get();$inventoryCost=$products->sum(fn($p)=>$p->stock_quantity*(float)($p->cost_price??0));$inventoryRetail=$products->sum(fn($p)=>$p->stock_quantity*(float)$p->product_price);$lowStock=$products->filter(fn($p)=>$p->is_low_stock)->count();$outOfStock=$products->where('stock_quantity',0)->count();$sales=Order::whereIn('status',['confirmed','completed'])->sum('total_amount');$purchases=PurchaseOrder::whereIn('status',['ordered','partial','received'])->sum('total_amount');$movementQuery=StockMovement::query();if($r->filled('from'))$movementQuery->whereDate('created_at','>=',$r->date('from'));if($r->filled('to'))$movementQuery->whereDate('created_at','<=',$r->date('to'));$movements=$movementQuery->select('type',DB::raw('SUM(quantity) as quantity'),DB::raw('COUNT(*) as events'))->groupBy('type')->orderBy('type')->get();$byCategory=$products->groupBy(fn($p)=>$p->categoryRelation?->name ?: $p->category ?: 'Uncategorized')->map(fn($items)=>['units'=>$items->sum('stock_quantity'),'cost'=>$items->sum(fn($p)=>$p->stock_quantity*(float)($p->cost_price??0)),'retail'=>$items->sum(fn($p)=>$p->stock_quantity*(float)$p->product_price)])->sortByDesc('retail');return view('reports.index',compact('inventoryCost','inventoryRetail','lowStock','outOfStock','sales','purchases','movements','byCategory'));}}
